<script setup lang="ts">
import {onMounted,onUnmounted,ref} from 'vue';import {tasksApi,type Task} from '@/lib/api';import TaskRow from '@/components/domain/TaskRow.vue';import {useEvents} from '@/composables/useEvents';import {useToast} from '@/composables/useToast';const rows=ref<Task[]>([]);const {toast}=useToast();async function load(){rows.value=await tasksApi.list()}onMounted(load);const {connected}=useEvents(e=>{if(e.type==='task_status')void load()});onUnmounted(()=>{});async function retry(id:number){await tasksApi.retry(id);toast('任务已重新排队','success');await load()}async function cancel(id:number){await tasksApi.cancel(id);toast('排队任务已取消','success');await load()}
</script>
<template><div class="space-y-5"><div class="flex items-center justify-between"><div><h2 class="text-xl font-semibold">执行队列</h2><p class="text-sm text-muted">任务状态通过 SSE 实时刷新</p></div><span class="text-xs text-muted">{{connected?'实时连接':'重连中'}}</span></div><div v-if="!rows.length" class="rounded-card border border-border p-6 text-muted">暂无任务</div><div class="space-y-3"><TaskRow v-for="task in rows" :key="task.id" :task="task" @retry="retry" @cancel="cancel"/></div></div></template>